1	import { app } from 'electron'
2	import { EventEmitter } from 'node:events'
3	import { createJsonStore, loadJsonObject } from './json-store'
4	
5	// 에이전트 실행 이력 — 에이전트가 수행한 작업(지시·단계·결과)을 저장해 나중에 되짚어볼 수 있게 한다.
6	// 메인에서 기록하므로 사이드바를 닫아도 남는다. userData/ai-agent-runs.json.
7	// 저장 기전(디바운스·원자적 쓰기·손상 복구)은 json-store.ts 가 맡는다 — 그 파일의 머리말 참고.
8	
9	export type AgentRunStatus = 'running' | 'done' | 'error' | 'cancelled'
10	export interface AgentRunStep { icon: string; text: string; tone?: 'ok' | 'warn' | 'muted' }
11	export interface AgentRun {
12	  id: string
13	  task: string
14	  startedAt: number
15	  endedAt?: number
16	  status: AgentRunStatus
17	  steps: AgentRunStep[]
18	  result?: string
19	  // 토큰 합계(CLI 세션 경로가 스텝마다 usage 를 방출할 때만 채워진다) — 효율 벤치·사용자 확인용.
20	  usage?: { input: number; cacheRead: number; cacheCreate: number; output: number; llmCalls: number }
21	}
22	export interface AgentRunSummary {
23	  id: string
24	  task: string
25	  startedAt: number
26	  endedAt?: number
27	  status: AgentRunStatus
28	  stepCount: number
29	}
30	
31	export const agentRunEvents = new EventEmitter()
32	
33	const MAX_RUNS = 50
34	const MAX_STEPS_PER_RUN = 120
35	const FILE_NAME = 'ai-agent-runs.json'
36	
37	let cache: AgentRun[] | null = null
38	let quitHooked = false
39	
40	const store = createJsonStore({
41	  fileName: FILE_NAME,
42	  label: '실행 이력',
43	  debounceMs: 400,
44	  snapshot: () => ({ version: 1, runs: all() }),
45	})
46	
47	function isValid(r: unknown): r is AgentRun {
48	  if (!r || typeof r !== 'object') return false
49	  const o = r as Record<string, unknown>
50	  return typeof o.id === 'string' && typeof o.task === 'string' && Array.isArray(o.steps)
51	}
52	
53	export function initAgentRuns(): void {
54	  if (!quitHooked) { quitHooked = true; try { app.on('before-quit', flushAgentRuns) } catch { /* ignore */ } }
55	  if (cache !== null) return
56	
57	  // 파일을 통째로 못 읽으면 loadJsonObject 가 고유 이름 백업을 남기고 null 을 준다.
58	  // (예전에는 백업 없이 빈 상태로 시작해, 다음 저장이 손상 파일을 영구히 덮어썼다.)
59	  const raw = loadJsonObject(FILE_NAME, '실행 이력', 'runs')
60	  if (!raw) { cache = []; return }
61	
62	  const rawRuns = Array.isArray(raw.runs) ? raw.runs : []
63	  cache = rawRuns.filter(isValid)
64	  // 파싱은 됐지만 일부 항목이 망가진 경우 — 정상 항목은 복구하고 버린 개수를 알린다.
65	  store.reportDropped(rawRuns.length - cache.length, cache.length)
66	  // 재시작 시 'running' 으로 남은 것은 중단된 것으로 정리
67	  for (const r of cache) { if (r.status === 'running') { r.status = 'cancelled'; r.endedAt = r.endedAt ?? r.startedAt } }
68	}
69	
70	function all(): AgentRun[] {
71	  if (cache === null) initAgentRuns()
72	  return cache ?? []
73	}
74	
75	function schedulePersist(): void {
76	  store.markDirty()
77	}
78	
79	export function flushAgentRuns(): void {
80	  store.flush()
81	}
82	
83	function summaryOf(r: AgentRun): AgentRunSummary {
84	  return { id: r.id, task: r.task, startedAt: r.startedAt, endedAt: r.endedAt, status: r.status, stepCount: r.steps.length }
85	}
86	
87	function emitChanged(): void {
88	  agentRunEvents.emit('changed', listAgentRuns())
89	}
90	
91	export function listAgentRuns(): AgentRunSummary[] {
92	  return all().slice().sort((a, b) => b.startedAt - a.startedAt).map(summaryOf)
93	}
94	
95	export function getAgentRun(id: string): AgentRun | null {
96	  return all().find((r) => r.id === id) ?? null
97	}
98	
99	// 실행 이력은 디스크에 평문으로 남는다. 비밀번호·카드번호·토큰처럼 남으면 안 되는 값은 가린다.
100	const CARD_LIKE = /\b(?:\d[ -]?){13,19}\b/g
101	const TOKEN_LIKE = /\b(?:sk|pk|ghp|xox[baprs])[-_][A-Za-z0-9_-]{12,}\b|\bBearer\s+[A-Za-z0-9._-]{12,}/gi
102	// 공백 없이 이어진 12자 이상 + 숫자·기호가 섞인 문자열 = 비밀번호일 가능성이 높다(URL·이메일은 제외).
103	const PASSWORD_LIKE = /(?<![\w./:@-])(?!https?:\/\/|www\.)(?=[^\s]{12,})(?=[^\s]*\d)(?=[^\s]*[^\w\s])(?![^\s]*@)[^\s]{12,}(?![\w./-])/g
104	
105	function maskSecrets(text: string): string {
106	  return String(text ?? '')
107	    .replace(TOKEN_LIKE, '[가림: 토큰]')
108	    .replace(CARD_LIKE, '[가림: 번호]')
109	    .replace(PASSWORD_LIKE, '[가림]')
110	}
111	
112	// 에이전트 이벤트를 사람이 읽는 단계로 변환(AiTab 라이브 트레이스와 동일 매핑).
113	type EventLike = { type: string; [k: string]: unknown }
114	function deriveStep(evt: EventLike): AgentRunStep | null {
115	  const s = (k: string): string => String(evt[k] ?? '')
116	  switch (evt.type) {
117	    case 'observe': return { icon: '🔍', text: `관찰 · 스텝 ${s('step')} · 요소 ${s('elements')}개`, tone: 'muted' }
118	    case 'thought': return evt.thought ? { icon: '💭', text: s('thought') } : null
119	    case 'action': return { icon: '⚙️', text: s('label') }
120	    case 'result': return { icon: evt.ok ? '✔️' : '✖️', text: s('detail'), tone: evt.ok ? 'ok' : 'warn' }
121	    case 'confirm': return { icon: '⏸️', text: `확인 필요: ${s('label')}`, tone: 'warn' }
122	    case 'ask': return { icon: '❓', text: s('message') }
123	    // 사용자 답변은 디스크(ai-agent-runs.json)에 영구 저장된다 → 비밀번호·카드번호가 평문으로 남지 않게 가린다.
124	    case 'answer': return { icon: '🗣️', text: `답변: ${maskSecrets(s('text'))}`, tone: 'muted' }
125	    case 'report': return { icon: '📄', text: `보고서: ${s('title')} (노트 ${s('notes')}개)`, tone: 'ok' }
126	    case 'done': return { icon: '🏁', text: s('message') || '완료', tone: 'ok' }
127	    case 'error': return { icon: '❌', text: s('message') || '오류', tone: 'warn' }
128	    case 'cancelled': return { icon: '⏹️', text: '중단됨', tone: 'muted' }
129	    default: return null
130	  }
131	}
132	
133	export function recordAgentEvent(runId: string, task: string, evt: EventLike): void {
134	  const list = all()
135	  let run = list.find((r) => r.id === runId)
136	
137	  if (evt.type === 'start') {
138	    if (run) return
139	    run = { id: runId, task: task || String(evt.task ?? '작업'), startedAt: Date.now(), status: 'running', steps: [] }
140	    list.unshift(run)
141	    if (list.length > MAX_RUNS) cache = list.slice(0, MAX_RUNS)
142	    schedulePersist(); emitChanged()
143	    return
144	  }
145	
146	  if (!run) {
147	    run = { id: runId, task: task || '작업', startedAt: Date.now(), status: 'running', steps: [] }
148	    list.unshift(run)
149	    if (list.length > MAX_RUNS) cache = list.slice(0, MAX_RUNS)
150	  }
151	
152	  if (evt.type === 'usage') {
153	    const n = (k: string): number => (typeof evt[k] === 'number' ? (evt[k] as number) : 0)
154	    const u = run.usage ?? { input: 0, cacheRead: 0, cacheCreate: 0, output: 0, llmCalls: 0 }
155	    u.input += n('input'); u.cacheRead += n('cacheRead'); u.cacheCreate += n('cacheCreate'); u.output += n('output'); u.llmCalls++
156	    run.usage = u
157	    schedulePersist()
158	    return
159	  }
160	
161	  const step = deriveStep(evt)
162	  if (step) {
163	    run.steps.push(step)
164	    // 상한 초과 시 최신(종료 마커 포함) 을 남기도록 오래된 단계를 버린다.
165	    if (run.steps.length > MAX_STEPS_PER_RUN) run.steps.splice(0, run.steps.length - MAX_STEPS_PER_RUN)
166	  }
167	
168	  let transitioned = false
169	  if (evt.type === 'done') { run.status = 'done'; run.endedAt = Date.now(); run.result = String(evt.message ?? ''); transitioned = true }
170	  else if (evt.type === 'error') { run.status = 'error'; run.endedAt = Date.now(); run.result = String(evt.message ?? ''); transitioned = true }
171	  else if (evt.type === 'cancelled') { run.status = 'cancelled'; run.endedAt = Date.now(); transitioned = true }
172	
173	  schedulePersist()
174	  if (transitioned) emitChanged() // 단계마다가 아니라 상태 전환 시에만 목록 갱신(라이브 트레이스는 별도 스트림)
175	}
176	
177	export function deleteAgentRun(id: string): void {
178	  const list = all()
179	  const idx = list.findIndex((r) => r.id === id)
180	  if (idx < 0) return
181	  list.splice(idx, 1)
182	  schedulePersist(); emitChanged()
183	}
184	
185	export function clearAgentRuns(): void {
186	  cache = []
187	  schedulePersist(); emitChanged()
188	}
