  const files: string[] = []
  if (reportNotes.length > 0) {
    const host = wcEnd ? (() => { try { return new URL(wcEnd.getURL()).hostname } catch { return '사이트' } })() : '사이트'
    const title = `${host} 분석 보고서 (부분)`
    const md = assembleReport(title, '', reportNotes, task)
