    if (saved.ok && saved.path) files.push(saved.path)
    emit({ type: 'report', title, markdown: md, notes: reportNotes.length, sources: [...seenNoteUrls], ...(saved.ok && saved.path ? { path: saved.path } : {}) })
  }
