178:async function pointForRef(wc: WebContents, ref: number): Promise<{ x: number; y: number; name: string } | null> {
303:async function pointHitsRef(wc: WebContents, ref: number, x: number, y: number): Promise<boolean> {
321:async function prepareClickPoint(wc: WebContents, ref: number, settleMs: number): Promise<
361:async function realClickRef(wc: WebContents, ref: number, prof: InputProfile = PROFILE_STRICT): Promise<{ ok: boolean; name: string } | null> {
376:async function verifyTyped(wc: WebContents, ref: number, text: string): Promise<boolean> {
487:async function ensureFieldCleared(wc: WebContents, ref: number): Promise<void> {
519:async function realTypeRef(wc: WebContents, ref: number, text: string, submit: boolean, prof: InputProfile = PROFILE_STRICT): Promise<{ ok: boolean; detail: string }> {
561:export async function hoverElement(wc: WebContents, ref: number): Promise<{ ok: boolean; detail: string }> {
588:export async function dragOnPage(wc: WebContents, spec: { ref?: number; xPct?: number; yPct?: number; toRef?: number; toXPct?: number; toYPct?: number }): Promise<{ ok: boolean; detail: string }> {
627:export async function pressKey(wc: WebContents, spec: { key: string; ref?: number }): Promise<{ ok: boolean; detail: string }> {
720:export async function resolveHref(wc: WebContents, ref: number): Promise<string | null> {
737:export async function resolveMediaSrc(wc: WebContents, ref: number): Promise<{ url: string; kind: 'image' | 'video' | 'link' } | null> {
1054:export async function observePage(wc: WebContents, opts?: { maxElements?: number; maxText?: number }): Promise<PageObservation | null> {
1066:function execScript(action: AgentAction): string {
1130:async function execSynthetic(wc: WebContents, action: AgentAction): Promise<{ ok: boolean; detail: string }> {
1157:export async function executeInPageAction(
1303:export async function dropFilesOnRef(wc: WebContents, ref: number, filePaths: string[]): Promise<{ ok: boolean; detail: string }> {

176	
177	// ref 의 화면(뷰포트) 중심 좌표를 구한다(호버·드래그용). top 문서 기준.
178	async function pointForRef(wc: WebContents, ref: number): Promise<{ x: number; y: number; name: string } | null> {
179	  try {
180	    return (await wc.executeJavaScript(`
181	(function(){
182	  ${PICK_FN}
183	  ${FRAME_OFFSET_FN}
184	  var el = pick(${ref}); if(!el) return null;
185	  try{ el.scrollIntoView({block:'center'}); }catch(e){}
186	  var r = el.getBoundingClientRect();
187	  var fo = frameOffset(el);
188	  return { x: Math.round(r.left + r.width/2 + fo.ox), y: Math.round(r.top + r.height/2 + fo.oy), name: (el.innerText||el.textContent||'').replace(/\\s+/g,' ').trim().slice(0,30) };
189	})()
190	`, true)) as { x: number; y: number; name: string } | null
191	  } catch { return null }
192	}
193	
194	async function viewportSize(wc: WebContents): Promise<{ w: number; h: number }> {
195	  try { return (await wc.executeJavaScript('({w:window.innerWidth,h:window.innerHeight})', true)) as { w: number; h: number } }
196	  catch { return { w: 1200, h: 800 } }
197	}
198	
199	// ===== 사람처럼 조작(human-like input) — 실제 마우스 이동 궤적 + trusted sendInputEvent =====
200	// 인스타그램·페이스북 등은 isTrusted 이벤트와 실제 마우스 움직임까지 봇 탐지에 쓴다. el.click()·dispatchEvent
201	// 같은 합성 이벤트는 isTrusted=false 라 걸릴 수 있으므로, 클릭·입력을 진짜 입력 이벤트로 보낸다(브라우저 그대로).
202	
203	const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms))
204	// 마지막 커서 위치를 WebContents 단위로 기억해 다음 이동이 그 자리에서 이어지도록(연속적인 궤적).
205	const lastMouse = new WeakMap<WebContents, { x: number; y: number }>()
206	const jitter = (amp: number): number => (Math.random() * 2 - 1) * amp
207	
208	// ===== 입력 속도 프로파일 =====
209	// 사람처럼 보이는 타이밍(궤적·타건 간격·반응 지연)은 봇 탐지 회피에 필요하지만, 모든 사이트에서 쓰면
210	// 클릭마다 0.5초·40자 입력에 3초가 들어 작업 전체가 느려진다(실측: build/bench-agent-cdp.mjs).
211	// 그래서 두 프로파일을 둔다 — 둘 다 **실제 입력 이벤트(trusted)** 를 쓰는 건 같고, 사람 흉내의
212	// "여유 시간"만 다르다. 봇 탐지가 실제로 도는 사이트에서만 strict 를 쓰고 나머지는 fast 로 간다.
213	interface InputProfile {
214	  moveStepMs: [number, number]     // 마우스 이동 한 스텝 지연
215	  movePauseChance: number          // 이동 중 멈칫할 확률
216	  reactionMs: [number, number]     // 요소를 인지하고 누르기까지
217	  holdMs: [number, number]         // 버튼을 누르고 있는 시간
218	  settleMs: number                 // 클릭 전 좌표 안정화 최대 대기(인페이지)
219	  typeMs: [number, number]         // 타건 간격(base, 지수 스케일)
220	  typeWordPause: boolean           // 단어·문장 경계에서 생각하는 시간
221	  overshoot: boolean               // 목표를 지나쳤다 되돌아오기
222	}
223	
224	const PROFILE_STRICT: InputProfile = {
225	  moveStepMs: [4, 2.2], movePauseChance: 0.06, reactionMs: [90, 220], holdMs: [40, 90],
226	  settleMs: 300, typeMs: [12, 3.1], typeWordPause: true, overshoot: true,
227	}
228	const PROFILE_FAST: InputProfile = {
229	  moveStepMs: [1, 1.2], movePauseChance: 0, reactionMs: [12, 25], holdMs: [12, 25],
230	  settleMs: 120, typeMs: [2, 1.6], typeWordPause: false, overshoot: false,
231	}
232	
233	// 정규분포 난수(Box-Muller) — 사람의 손떨림·조준 오차는 균등분포가 아니라 정규분포에 가깝다.
234	function gauss(sigma: number): number {
235	  const u = Math.max(1e-9, Math.random())
236	  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random()) * sigma
237	}
238	
239	// 이전 위치에서 (x,y)로 사람처럼 이동.
240	// 사람의 마우스는 ① 직선이 아니라 완만한 곡선(베지어) ② 매번 다른 가속 프로파일 ③ 목표를 살짝 지나쳤다
241	// 되돌아오는 보정 ④ 이동 중 짧은 멈칫 을 보인다. 직선+고정 ease+균등 지연은 궤적 통계만으로 봇으로 분류된다.
242	async function humanMoveTo(wc: WebContents, x: number, y: number, prof: InputProfile = PROFILE_STRICT): Promise<void> {
243	  const prev = lastMouse.get(wc) ?? { x: Math.round(x - 60 + jitter(20)), y: Math.round(y - 40 + jitter(20)) }
244	  const dx = x - prev.x, dy = y - prev.y
245	  const dist = Math.hypot(dx, dy)
246	  const steps = Math.max(6, Math.min(28, Math.round(dist / (16 + Math.random() * 12))))
247	  // 제어점 — 이동 직선의 수직 방향으로 거리 비례 편차를 줘 완만한 곡선을 만든다(매번 방향·크기 랜덤).
248	  const nx = dist > 0 ? -dy / dist : 0
249	  const ny = dist > 0 ? dx / dist : 0
250	  const bow = (Math.random() * 0.18 + 0.04) * dist * (Math.random() < 0.5 ? -1 : 1)
251	  const c1x = prev.x + dx * 0.3 + nx * bow, c1y = prev.y + dy * 0.3 + ny * bow
252	  const c2x = prev.x + dx * 0.7 + nx * bow * 0.6, c2y = prev.y + dy * 0.7 + ny * bow * 0.6
253	  // 목표를 살짝 지나쳤다 되돌아오는 오버슈트(먼 거리일수록 자주).
254	  const overshoot = prof.overshoot && dist > 120 && Math.random() < 0.45
255	  const ox = overshoot ? x + (dx / dist) * (4 + Math.random() * 10) : x
256	  const oy = overshoot ? y + (dy / dist) * (4 + Math.random() * 10) : y
257	  const pow = 1.6 + Math.random() * 1.2 // 가속 프로파일을 이동마다 바꾼다
258	  const bez = (t: number, p0: number, p1: number, p2: number, p3: number): number => {
259	    const u = 1 - t
260	    return u * u * u * p0 + 3 * u * u * t * p1 + 3 * u * t * t * p2 + t * t * t * p3
261	  }
262	  for (let i = 1; i <= steps; i++) {
263	    const t = i / steps
264	    const e = t < 0.5 ? Math.pow(2 * t, pow) / 2 : 1 - Math.pow(2 * (1 - t), pow) / 2
265	    const mx = Math.round(bez(e, prev.x, c1x, c2x, ox) + (i < steps ? jitter(1.5) : 0))
266	    const my = Math.round(bez(e, prev.y, c1y, c2y, oy) + (i < steps ? jitter(1.5) : 0))
267	    try { wc.sendInputEvent({ type: 'mouseMove', x: mx, y: my }) } catch { /* top-level 만 */ }
268	    // 로그정규에 가까운 지연 + 가끔 멈칫(사람은 이동 중 목표를 다시 확인한다).
269	    await sleep(Math.round(prof.moveStepMs[0] + Math.exp(Math.random() * prof.moveStepMs[1]))
270	      + (Math.random() < prof.movePauseChance ? 40 + Math.floor(Math.random() * 90) : 0))
271	  }
272	  if (overshoot) { // 지나친 만큼 되돌아오는 보정 이동
273	    await sleep(20 + Math.floor(Math.random() * 50))
274	    for (let i = 1; i <= 3; i++) {
275	      const t = i / 3
276	      try { wc.sendInputEvent({ type: 'mouseMove', x: Math.round(ox + (x - ox) * t), y: Math.round(oy + (y - oy) * t) }) } catch { /* ignore */ }
277	      await sleep(8 + Math.floor(Math.random() * 14))
278	    }
279	  }
280	  const fx = Math.round(x), fy = Math.round(y)
281	  try { wc.sendInputEvent({ type: 'mouseMove', x: fx, y: fy }) } catch { /* ignore */ }
282	  lastMouse.set(wc, { x: fx, y: fy })
283	}
284	
285	// 좌표(top 창 CSS px)에 실제 클릭 — 이동 → 잠깐 멈춤 → 버튼 down → 사람 같은 클릭 지속 → up.
286	// down/up 좌표는 미세하게 어긋난다(사람은 누르는 동안 손이 완전히 멈추지 않는다).
287	async function realClickXY(wc: WebContents, x: number, y: number, prof: InputProfile = PROFILE_STRICT): Promise<void> {
288	  try { wc.focus() } catch { /* ignore */ }
289	  await humanMoveTo(wc, x, y, prof)
290	  // 요소를 인지하고 누르기까지의 반응 지연 — 즉시 클릭은 사람에게 없는 리듬이다.
291	  await sleep(prof.reactionMs[0] + Math.floor(Math.random() * prof.reactionMs[1]))
292	  const px = Math.round(x), py = Math.round(y)
293	  wc.sendInputEvent({ type: 'mouseDown', x: px, y: py, button: 'left', clickCount: 1 })
294	  await sleep(prof.holdMs[0] + Math.floor(Math.random() * prof.holdMs[1]))
295	  const ux = px + (Math.random() < 0.4 ? Math.round(jitter(1)) : 0)
296	  const uy = py + (Math.random() < 0.4 ? Math.round(jitter(1)) : 0)
297	  wc.sendInputEvent({ type: 'mouseUp', x: ux, y: uy, button: 'left', clickCount: 1 })
298	  lastMouse.set(wc, { x: ux, y: uy })
299	}
300	
301	// 클릭 지점이 실제로 그 요소인지 확인 — 스티키 헤더·쿠키 배너·로딩 오버레이가 위를 덮고 있으면
302	// 좌표만 보고 누르는 순간 엉뚱한 것이 눌린다. top 문서 좌표 기준(프레임 안 요소는 검사 생략).
303	async function pointHitsRef(wc: WebContents, ref: number, x: number, y: number): Promise<boolean> {
304	  try {
305	    return (await wc.executeJavaScript(`
306	(function(){
307	  ${PICK_FN}
308	  var el = pick(${ref}); if(!el) return false;
309	  try { if (el.ownerDocument !== document) return true; } catch(e) { return true; }
310	  var hit = document.elementFromPoint(${Math.round(x)}, ${Math.round(y)});
311	  if (!hit) return false;
312	  return hit === el || el.contains(hit) || (hit.contains && hit.contains(el));
313	})()
314	`, true)) as boolean
315	  } catch { return true } // 검사 자체가 실패하면 막지 않는다(오탐으로 조작을 멈추지 않도록)
316	}
317	
318	// 클릭 준비를 인페이지에서 한 번에 처리한다 — 스크롤 → 좌표 안정화(rAF) → 좌표 계산 → 가림 검사.
319	// 예전에는 JS 왕복 4회 + 고정 대기 120·180ms 로 나뉘어 있어 클릭마다 수백 ms 를 그냥 버렸다.
320	// 안정화는 고정 대기가 아니라 "연속 두 프레임에서 좌표가 같으면 통과" 라 대개 훨씬 빨리 끝난다.
321	async function prepareClickPoint(wc: WebContents, ref: number, settleMs: number): Promise<
322	{ x: number; y: number; name: string; w: number; h: number; vw: number; vh: number; occluded: boolean } | null> {
323	  try {
324	    return (await wc.executeJavaScript(`
325	(function(){
326	  ${PICK_FN}
327	  ${FRAME_OFFSET_FN}
328	  var el = pick(${ref}); if(!el) return null;
329	  try{ el.scrollIntoView({block:'center'}); }catch(e){}
330	  var deadline = Date.now() + ${Math.max(0, Math.round(settleMs))};
331	  function rect(){ var r = el.getBoundingClientRect(); var fo = frameOffset(el);
332	    return { x: r.left + r.width/2 + fo.ox, y: r.top + r.height/2 + fo.oy, w: r.width, h: r.height }; }
333	  function finish(r){
334	    var name = (el.innerText||el.textContent||'').replace(/\\s+/g,' ').trim().slice(0,30);
335	    var occluded = false;
336	    try {
337	      if (el.ownerDocument === document) {
338	        var hit = document.elementFromPoint(Math.round(r.x), Math.round(r.y));
339	        occluded = !!hit && !(hit === el || el.contains(hit) || (hit.contains && hit.contains(el)));
340	      }
341	    } catch(e){}
342	    return { x: r.x, y: r.y, name: name, w: r.w, h: r.h, vw: innerWidth, vh: innerHeight, occluded: occluded };
343	  }
344	  return new Promise(function(resolve){
345	    var prev = rect();
346	    function step(){
347	      var cur = rect();
348	      var stable = Math.abs(cur.x - prev.x) < 1 && Math.abs(cur.y - prev.y) < 1;
349	      if (stable || Date.now() > deadline) { resolve(finish(cur)); return; }
350	      prev = cur;
351	      requestAnimationFrame(step);
352	    }
353	    requestAnimationFrame(step);
354	  });
355	})()
356	`, true)) as { x: number; y: number; name: string; w: number; h: number; vw: number; vh: number; occluded: boolean } | null
357	  } catch { return null }
358	}
359	
360	// ref 의 화면 좌표를 구하고(scrollIntoView 포함) 뷰포트 안이면 실제 클릭. 좌표를 못 구하거나 화면 밖이면 null.
361	async function realClickRef(wc: WebContents, ref: number, prof: InputProfile = PROFILE_STRICT): Promise<{ ok: boolean; name: string } | null> {
362	  const p = await prepareClickPoint(wc, ref, prof.settleMs)
363	  if (!p) return null
364	  if (p.occluded) return null // 다른 것이 덮고 있음 → 합성 폴백
365	  if (p.x < 0 || p.y < 0 || p.x > p.vw || p.y > p.vh) return null // 화면 밖 → 합성 폴백
366	  // 요소 정중앙을 픽셀 단위로 반복해 찍는 것은 사람에게 불가능하다 — 요소 크기에 비례한 정규분포 오차.
367	  const sx = Math.min(6, Math.max(1, p.w / 6))
368	  const sy = Math.min(5, Math.max(1, p.h / 6))
369	  const tx = Math.max(1, Math.min(p.vw - 1, Math.round(p.x + gauss(sx))))
370	  const ty = Math.max(1, Math.min(p.vh - 1, Math.round(p.y + gauss(sy))))
371	  await realClickXY(wc, tx, ty, prof)
372	  return { ok: true, name: p.name }
373	}
374	
375	// 입력값이 실제로 들어갔는지 검증(합성 폴백 판단용) — 첫 조각이 요소 값/본문에 있으면 성공으로 본다.

