304	  ipcMain.handle(IPC.ai.exportWebhook, async (e, args: { rows: unknown[]; url?: string }) => {
305	    if (!isTrustedSender(e)) return { ok: false, detail: '권한 없음' }
306	    const url = (args?.url || getSetting('ai').webhookUrl || '').trim()
307	    if (!/^https?:\/\//i.test(url)) return { ok: false, detail: '웹훅 URL 이 설정되지 않았습니다(설정 > AI).' }
308	    const rows = Array.isArray(args?.rows) ? args.rows.slice(0, 5000) : []
309	    const body = JSON.stringify({ source: 'ezBrowser', count: rows.length, rows, at: Date.now() })
310	    return await new Promise<{ ok: boolean; detail: string }>((resolve) => {
311	      try {
312	        const req = net.request({ url, method: 'POST' })
313	        req.setHeader('content-type', 'application/json')
314	        const timer = setTimeout(() => { try { req.abort() } catch { /* ignore */ }; resolve({ ok: false, detail: '시간 초과' }) }, 20000)
315	        req.on('response', (resp) => {
316	          const status = resp.statusCode ?? 0
317	          resp.on('data', () => { /* drain */ })
318	          resp.on('end', () => { clearTimeout(timer); resolve(status >= 200 && status < 400 ? { ok: true, detail: `전송됨 (${status})` } : { ok: false, detail: `실패 (${status})` }) })
319	          resp.on('error', () => { clearTimeout(timer); resolve({ ok: false, detail: '응답 오류' }) })
320	        })
321	        req.on('error', (err) => { clearTimeout(timer); resolve({ ok: false, detail: err.message }) })
322	        req.write(body); req.end()
323	      } catch (err) { resolve({ ok: false, detail: String(err) }) }
324	    })
325	  })
