  }
  const vp = await viewportSize(wc)
  const x = Math.round(xPct / 100 * vp.w)
  const y = Math.round(yPct / 100 * vp.h)
  await realClickXY(wc, x, y, prof)
  return { ok: true, detail: `화면 클릭 ${x},${y}` }

