121	// ── 타깃 발견 ───────────────────────────────────────────────────────────
122	
123	export async function getTargetList(port) {
124	  const res = await fetch(`http://127.0.0.1:${port}/json/list`)
125	  if (!res.ok) throw new Error(`/json/list HTTP ${res.status}`)
126	  return res.json()
127	}
128	
129	/** 외피(브라우저 크롬 UI) 타깃인가 — file://…/index.html?windowId=… */
130	export function isShellTarget(t) {
131	  return t.type === 'page' && typeof t.url === 'string'
132	    && t.url.startsWith('file://') && t.url.includes('index.html') && t.url.includes('windowId=')
133	}
134	
135	export async function waitForShellTarget(port, timeoutMs = 30_000) {
136	  let lastList = []
137	  return pollUntil(async () => {
138	    lastList = await getTargetList(port)
139	    return lastList.find(isShellTarget) ?? null
140	  }, { timeoutMs, intervalMs: 500, label: 'shell CDP target' }).catch((err) => {
141	    const summary = lastList.map((t) => `${t.type}:${t.url}`).join('\n  ')
142	    throw new Error(`${err.message}\n마지막 타깃 목록:\n  ${summary || '(없음)'}`)
143	  })
144	}
145	
146	export async function waitForTargetByUrlPredicate(port, predicate, label, timeoutMs = 15_000) {
147	  return pollUntil(async () => {
148	    const list = await getTargetList(port)
149	    return list.find((t) => t.type === 'page' && typeof t.url === 'string' && predicate(t.url)) ?? null
150	  }, { timeoutMs, intervalMs: 300, label })
151	}
152	
153	// ── 접속 견고화 (여기가 이 모듈의 존재 이유) ─────────────────────────────
154	
155	/**
156	 * CDP 디버그 포트가 **정말로 비었는지** 확인한다.
157	 *
158	 * 앞선 실행이 남긴 인스턴스가 같은 포트를 쥐고 있으면, 새 앱을 띄워도 `/json/list` 는
159	 * **좀비의 타깃**을 돌려준다. 그 렌더러는 이미 죽어 CDP 명령이 영영 응답하지 않고,
160	 * 하네스는 원인을 알 수 없는 전면 실패로 무너진다(2026-09-06 실측 — INFRA 실패의 주원인).
161	 *
162	 * **연결 거부만 "비었음"이다.** 타임아웃·리셋은 소켓만 쥔 좀비가 응답을 못 하는 상태일 수
163	 * 있으므로 점유로 간주한다(좀비는 TCP 는 받고 HTTP 는 답하지 않는다).
164	 */
165	export async function waitForPortFree(port, timeoutMs = 12_000) {
166	  const deadline = Date.now() + timeoutMs
167	  while (Date.now() < deadline) {
168	    try {
169	      const res = await fetch(`http://127.0.0.1:${port}/json/version`, { signal: AbortSignal.timeout(1500) })
170	      if (!res.ok) return true
171	    } catch (err) {
172	      const code = err?.cause?.code ?? err?.code
173	      if (code === 'ECONNREFUSED' || code === 'ENOTFOUND') return true
174	    }
175	    await sleep(500)
176	  }
177	  // 여기까지 왔다는 것은 누군가 그 포트를 쥐고 있다는 뜻이다.
178	  // **누가** 쥐고 있는지 찍어 준다 - 이게 없으면 "앱이 안 뜬다" 로 오해하게 된다(임무 23 실화).
179	  try {
180	    const { describePortOwner } = await import('./ports.mjs')
181	    const owner = describePortOwner(port)
182	    if (owner) console.warn(`[cdp] 포트 ${port} 를 ${owner} 가 점유 중 - 앞선 실행의 잔재일 수 있다`)
183	  } catch { /* 진단 실패는 무시 */ }
184	  return false
185	}
186	
187	/**
188	 * 이미 연결한 세션이 **실제로 응답하는지** 확인한다(필요하면 기다린다).
189	 *
190	 * 갓 만들어진 창의 타깃은 `/json/list` 에 먼저 나타나고 렌더러 준비는 그 뒤다. 곧바로 보낸
191	 * 첫 명령이 한참 응답하지 않을 수 있다(2026-09-06 실측: 같은 머신에서 20ms ↔ 16초).
192	 */
193	export async function ensureSessionReady(session, { totalMs = 45_000, probeMs = 15_000 } = {}) {
194	  const deadline = Date.now() + totalMs
195	  let lastErr = null
196	  while (Date.now() < deadline) {
197	    try {
198	      await session.send('Runtime.enable', {}, probeMs)
199	      const probe = await session.send('Runtime.evaluate', { expression: '1+1', returnByValue: true }, probeMs)
200	      if (probe?.result?.value === 2) return true
201	    } catch (err) { lastErr = err }
202	    await sleep(300)
203	  }
204	  throw new Error(`세션 응답 확인 실패(${session.label})${lastErr ? ` — ${lastErr.message}` : ''}`)
205	}
206	
207	/**
208	 * 외피 CDP 세션을 **실제로 응답하는 상태로** 확보한다.
209	 *
210	 * 타깃 재발견 → 연결 → Runtime.enable → 프로브 evaluate 를 성공할 때까지 반복하고,
211	 * 응답이 없으면 그 세션을 버리고 새로 연결한다(타깃 스왑 대응).
212	 *
213	 * 프로브 대기는 **짧게 시작해 크게 늘린다**: 갓 패키징한 exe 는 첫 실행에서 백신 검사·콜드
214	 * 캐시 때문에 CDP 응답이 수십 초 늦을 수 있고, 짧은 타임아웃으로 재연결만 반복하면
215	 * **늦게 오는 응답을 매번 버려** 영원히 실패한다(실측: 45초를 18번 헛되이 씀).
216	 */
217	export async function connectShellSessionReady(port, { totalMs = 90_000, label = 'chrome-shell', log = null } = {}) {
218	  const deadline = Date.now() + totalMs
219	  const schedule = [8_000, 20_000, 30_000, 30_000]
220	  let attempt = 0
221	  let lastErr = null
222	  while (Date.now() < deadline) {
223	    const remain = deadline - Date.now()
224	    const probeMs = Math.max(2_000, Math.min(schedule[Math.min(attempt, schedule.length - 1)], remain))
225	    attempt += 1
226	    let session = null
227	    try {
228	      const target = await waitForShellTarget(port, Math.max(1_000, deadline - Date.now()))
229	      session = await connectSession(target, label)
230	      await session.send('Runtime.enable', {}, probeMs)
231	      const probe = await session.send('Runtime.evaluate', {
232	        expression: '1+1', returnByValue: true,
233	      }, probeMs)
234	      if (probe?.result?.value !== 2) throw new Error(`프로브 값 이상: ${JSON.stringify(probe)}`)
235	      if (attempt > 1 && log) log(`외피 세션 확보 (재시도 ${attempt}회차)`)
236	      return session
237	    } catch (err) {
238	      lastErr = err
239	      try { session?.close() } catch { /* ignore */ }
240	      await sleep(500)
241	    }
242	  }
243	  throw new Error(`외피 CDP 세션 확보 실패(${totalMs}ms, ${attempt}회 시도)${lastErr ? ` — 마지막 오류: ${lastErr.message}` : ''}`)
244	}
245

