  'waiting-user': { icon: '❓', label: '확인 대기', tone: 'warn' },
  retrying: { icon: '🔄', label: '재시도 대기', tone: 'warn' },
  interrupted: { icon: '⏳', label: '미완료', tone: 'warn' },
  'needs-verify': { icon: '🔍', label: '확인 필요', tone: 'warn' },
  completed: { icon: '✅', label: '완료', tone: 'ok' },
