        case 'cancelled':
          if (!job.lastResult?.startsWith('안전 중단') && !job.lastResult?.startsWith('건너뜀')) {
            job.lastResult = job.autoConfirm ? '중단됨' : '민감 동작 확인 없음으로 이번 실행 취소'
