    task = (list || []).find((x) => x.id === created.id) ?? null
    if (!task) continue
    if (task.stepsUsed !== lastStep) { lastStep = task.stepsUsed; process.stdout.write(`  단계 ${task.stepsUsed} · ${task.state}\\r`) }
