  }"""
new_poll = """  const TERMINAL = new Set(['completed', 'failed', 'cancelled', 'needs-verify', 'interrupted'])
  const deadline = Date.now() + (sustain ? sustainMs + 120000 : args.perTaskMs + 30000)
  let task = null
  let lastStep = -1
  // 지속 실행에서는 "살아서 구간을 넘기고 있는가" 를 시계열로 기록한다 — 한 번 길게 도는 것과
