const VK_MAP = {} // 'a'..'z' → 65..90, '0'..'9' → 48..57 (미국 키보드 배열 기준, Chromium 표준)
for (let c = 0; c < 26; c++) VK_MAP[String.fromCharCode(97 + c)] = 65 + c
