  const low = String(key).toLowerCase()
  if (VK_MAP[low] != null) { params.windowsVirtualKeyCode = VK_MAP[low]; params.nativeVirtualKeyCode = VK_MAP[low]; params.code = /^[0-9]$/.test(low) ? `Digit${low}` : `Key${low.toUpperCase()}` }
  else if (NAMED_VK[key] != null) { params.windowsVirtualKeyCode = NAMED_VK[key]; params.nativeVirtualKeyCode = NAMED_VK[key]; params.code = NAMED_CODE[key] }
