    check('NC-T5', '[음성 대조] 일시정지를 걸지 않으면(= 정지가 동작을 막지 못하는 상황) T5 판정이 실패한다',
      !t5Verdict,
      `클릭 진행=${moved} · 일시정지 호출 없음 · 클릭 ${h1}→${h2}(늘어야 정상) · 상태=${stateOf(st)}`
      + ` · T5 판정=${t5Verdict ? 'PASS(← 검출력 없음)' : 'FAIL(정상 — 결함을 잡았다)'}`)
    await cancelTask(id)
