// 새 판정식의 검출력 확인(음성 대조) — 제품이 고쳐지기 전 문자열이 들어오면 FAIL 이 나야 한다.
function judge(resultText, stateBeforeCancel){
  const saysCancelled=/중단|취소/.test(resultText);
  const readsAsSuccess=resultText.length>0 && !saysCancelled;
  return !(stateBeforeCancel==='running' && readsAsSuccess);  // true = PASS
}
const cases=[
 ['늦은 완료 보고','running',false,'고치기 전 제품 문자열(성공처럼 읽힘) → 잡아야 함'],
 ['사용자가 중단했습니다. (중단 직전 모델이 보고한 내용: 늦은 완료 보고)','running',true,'고친 뒤 문자열 → 통과해야 함'],
 ['','running',true,'result 없음 → 통과'],
 ['작업을 완료했습니다.','running',false,'명백한 성공 문구 → 잡아야 함'],
];
let f=0;
for(const [t,s,want,why] of cases){const got=judge(t,s);const ok=got===want;if(!ok)f++;console.log((ok?'PASS':'FAIL')+'  '+why+' => judge='+got);}
console.log(f===0?'판정식 검출력 확인 OK':'판정식 결함 '+f);
process.exit(f?1:0)
"

